import numpy as np
def equation(t, A, params):
    p = params
    return (p[0] + p[1]*A**p[2] + p[3]*t*A**p[4] + p[5]*t**2*A**p[6] + p[7]*t**p[8]*A**p[9])

import numpy as np
base=[np.ones_like(t),t,t**2,A,A**2,A**3,t*A,t*A**2,t**2*A]
def r2(cols):
    X=np.column_stack(cols); c=np.linalg.lstsq(X,dA_dt,rcond=None)[0]
    return float(np.mean((dA_dt-X@c)**2)/np.var(dA_dt))
print('base',r2(base))
extra={'1/t':1/t,'log t':np.log(t),'sqrt t':np.sqrt(t),'exp(-t)':np.exp(-t),'exp(t/10)':np.exp(t/10),'t^3':t**3,'1/t^2':1/t**2,'exp(-1/t)':np.exp(-1/t)}
